```javascript
function startTimer(seconds, onTick, onDone) {
  let remaining = seconds;
  const id = setInterval(() => {
    remaining -= 1;
    onTick(remaining);
    if (remaining <= 0) {
      clearInterval(id);
      onDone();
    }
  }, 1000);
  return () => clearInterval(id);
}
```

```python
def binary_search(values, target):
    low, high = 0, len(values) - 1
    while low <= high:
        mid = (low + high) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
```

